        import org.apache.log4j.Logger;

        import sailpoint.object.Identity;

        Logger logger = Logger.getLogger("IAM_COE_BIRTHRIGHT_PROVISIONING");
        if (logger.isTraceEnabled()) {
        logger.trace("Alpha-Workflow-Immediate-Termination -> Entered to Auditing - Workflow Start Step!!!");
        }
        Identity identityObject = context.getObjectByName(Identity.class, identityName);
        String action = alphaStartAuditActionName;
        logger.debug("Alpha-Workflow-Immediate-Termination - Entered to Auditing - Workflow Start Step -> Termination Start Audit : "+action);
        String targetIdentity = identityObject.getDisplayName();
        logger.debug("Alpha-Workflow-Immediate-Termination - Entered to Auditing - Workflow Start Step -> Identity : "+targetIdentity);
        if (identityObject != null) {
        logger.debug("Alpha-Workflow-Immediate-Termination - Entered to Auditing - Workflow Start Step -> Decaching Identity Object");
        context.decache(identityObject);
        }
        if (logger.isTraceEnabled()) {
        logger.trace("Alpha-Workflow-Immediate-Termination -> Auditing - Workflow Start Step Ended!!!");
        }
        return createAuditEvent(wfcontext.getWorkflow().getName(), targetIdentity, action,null,null,null,null,null,null,null,null,null,null);

        import java.util.Map;
        import java.util.HashMap;

        import org.apache.log4j.Logger;

        import sailpoint.object.ProvisioningPlan;
        import sailpoint.object.ProvisioningPlan.AccountRequest.Operation;

        Logger logger = Logger.getLogger("iiq.alpha.Alpha-WorkFlow-Leaver");
        logger.debug("Alpha-Workflow-leaver -> Entered to Build Plan Step!!!");


        plan = buildProvisioningPlan(plan,identityName,ProvisioningPlan.AccountRequest.Operation.Disable);
        if (plan != null) {
        logger.debug("Alpha-Workflow-Immediate-Termination -> First Level Plan : "+plan.toXml());
        }

        Map attributeRequestMap = new HashMap();
        attributeRequestMap.put("AC_NewParent","OU=DisabledUsers,OU=Users,OU=Alpha,DC=tcs,DC=sailpointiamcoe,DC=com");

        String applicationName = "Alpha - Active Directory";

        plan = buildProvisioningPlan_Modify(plan,identityName,applicationName,"primaryAccount",attributeRequestMap);
        plan = buildProvisioningPlan_Modify(plan,identityName,applicationName,"privilegedAccount",attributeRequestMap);
        plan = buildProvisioningPlan_Modify(plan,identityName,applicationName,"secondaryAccount",attributeRequestMap);
        if (plan != null) {
        logger.debug("Alpha-Workflow-Immediate-Termination -> Second Level Plan : "+plan.toXml());
        }
        return plan;

Logger log = Logger.getLogger("iiq.alpha.workflow.Alpha-WorkFlow-Joiner");
Map map = getWorkflowFailures(wfcontext);
log.debug("failureMap:"+map);
if(null!=map && map.size()>0)
{
wfcontext.setVariable("alphaWorkflowFailureMap",map);
return true;
}
else
{
return false;
}

          import org.apache.log4j.Logger;

          import java.util.Map;
          import java.util.HashMap;

          Logger logger = Logger.getLogger("iiq.alpha.Alpha-WorkFlow-Leaver");

          logger.trace("Alpha-Workflow-Immediate-Termination -> Entered to Send Joiner Emails Step (emailArgList Argument)!!!");

          String customObjectName = "Alpha-Custom-Termination Custom Object";
          String emailTemplate = (String) getValueFromCustomObject(customObjectName,"terminationSuccess_emailTemplate");

          Identity identityObject = context.getObjectByName(Identity.class,identityName);

          Map successEmailArgs = emailArgumentsList(emailTemplate, identityObject, null, null);
          return successEmailArgs;

        import org.apache.log4j.Logger;

        import sailpoint.object.Identity;

        Logger logger = Logger.getLogger("IAM_COE_BIRTHRIGHT_PROVISIONING");
        if (logger.isTraceEnabled()) {
        logger.trace("Alpha-Workflow-Immediate-Termination -> Entered to Auditing - Termination Success Step!!!");
        }
        Identity identityObject = context.getObjectByName(Identity.class, identityName);
        String action = alphaSuccessAuditActionName;
        logger.debug("Alpha-Workflow-Immediate-Termination - Auditing - Termination Success -> Termination Start Audit : "+action);
        String targetIdentity = identityObject.getDisplayName();
        logger.debug("Alpha-Workflow-Immediate-Termination - Auditing - Termination Success -> Identity : "+targetIdentity);
        if (identityObject != null) {
        logger.debug("Alpha-Workflow-Immediate-Termination - Auditing - Termination Success -> Decaching Identity Object");
        context.decache(identityObject);
        }
        if (logger.isTraceEnabled()) {
        logger.trace("Alpha-Workflow-Immediate-Termination -> Auditing - Termination Success Step Ended!!!");
        }
        return createAuditEvent(wfcontext.getWorkflow().getName(), targetIdentity, action,null,null,null,null,null,null,"COMMITED",null,null,null);

